structure.mermaidSource:
flowchart TD
  start["Início: Verbo em -IR com 'e' no radical"] --> dec_grupo{"Pertence ao grupo de alternância e -> i?"}
  dec_grupo -- "Não" --> res_regular["Resultado: Aplicar conjugação regular padrão de -IR"]
  dec_grupo -- "Sim" --> dec_modo{"Qual o modo e tempo verbal?"}
  dec_modo -- "Presente do Subjuntivo" --> res_subj["Resultado: 'i' em TODAS as pessoas (que eu previna, agrida, compita)"]
  dec_modo -- "Presente do Indicativo" --> dec_pessoa_ind{"Qual a pessoa gramatical no Indicativo?"}
  dec_modo -- "Demais Tempos/Modos" --> res_outros["Resultado: Radical mantém 'e' (preveniu, agredia, competirá)"]
  dec_pessoa_ind -- "1ª p. sing. (Eu)" --> res_ind_1p["Resultado: 'e' vira 'i' no radical (eu previno, agrido, compito)"]
  dec_pessoa_ind -- "Nós / Vós (Arrizotônicas)" --> res_ind_arriz["Resultado: Mantém 'e' (nós prevenimos, nós agredimos, nós competimos)"]
  dec_pessoa_ind -- "Tu / Ele / Eles (Rizotônicas)" --> dec_subtipo{"Subgrupo agredir ou prevenir/competir?"}
  dec_subtipo -- "Agredir / Progredir" --> res_ind_agredir["Resultado: Mantém 'i' nas rizotônicas (tu agrides, ele agride, eles agridem)"]
  dec_subtipo -- "Prevenir / Competir" --> res_ind_prevenir["Resultado: Mantém 'e' nas rizotônicas (tu prevines, ele previne, eles previnem)"]
